insert into public.places (name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,verified,trust_score,is_active,content_review_status,tags)
select v.name,v.category,v.place_type,v.city,v.address,v.lat,v.lon,v.slug,v.short_description,v.long_description,v.source_url,'curated_seed',false,85,true,'source_backed',v.tags::jsonb
from (values
('Hz. Nuh Camii ve Türbesi','Tarih','cami ve türbe','Şırnak','Cizre, Şırnak',37.328,42.190,'curated-sirnak-hz-nuh-camii','Cizre’de Hz. Nuh’a atfedilen türbe ile birlikte anılan tarihî cami.','Cizre’nin tarihî merkezindeki cami ve türbe, kentin dinî ve kültürel ziyaret noktalarındandır.','https://sirnak.gov.tr/turizm','["tarih","cami","cizre"]'),
('Mem û Zîn Türbesi','Tarih','türbe','Şırnak','Cizre, Şırnak',37.329,42.188,'curated-sirnak-mem-u-zin-turbesi','Mem û Zîn anlatısıyla ilişkilendirilen Cizre’deki tarihî ziyaret noktası.','Klasik Kürt edebiyatında önemli yeri olan Mem û Zîn hikâyesiyle ilişkilendirilen türbe, Cizre’nin kültürel miras rotasındadır.','https://sirnak.gov.tr/turizm','["kültür","tarih","cizre"]'),
('Yafes Köprüsü','Tarih','tarihi köprü','Şırnak','Cizre, Dicle Nehri, Şırnak',37.330,42.190,'curated-sirnak-yafes-koprusu','Cizre’de Dicle çevresindeki tarihî geçiş noktası.','Yafes Köprüsü, Cizre’nin tarihî ulaşım ağı ve Dicle çevresindeki kültürel mirasla ilişkilendirilen yapılardandır.','https://sirnak.ktb.gov.tr/TR-372051/sirnak.html','["tarihi yapı","köprü","cizre"]'),
('Kasrik Köprüsü','Tarih','tarihi köprü','Şırnak','Kasrik, Şırnak',37.405,42.190,'curated-sirnak-kasrik-koprusu','Kasrik Boğazı’ndaki tarihî taş köprü.','Kasrik çevresindeki tarihî geçiş yapılarından olan köprü, boğazın eski ulaşım güzergâhını ve taş işçiliğini yansıtır.','https://sirnak.ktb.gov.tr/TR-372051/sirnak.html','["tarih","köprü","kasrik"]')
) as v(name,category,place_type,city,address,lat,lon,slug,short_description,long_description,source_url,tags)
where not exists (select 1 from public.places p where p.slug=v.slug);
update public.places set is_active=false where slug in ('osm-node-12406597793','osm-node-8046289768') and city='Samsun' and is_active=true;